159		assertEntry(t, graph, "extra", nil, nil)
160		assertConsistent(t, graph)
161	
162		// The same offending downstream listed first reports the same named error;
163		// input order must not swap it for any other complaint.
164		err = Register(graph, Dataset{Name: "mid"}, []string{"leaf", "extra"})
165		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
